export function getPreviewMode(search = '') {
  const params = new URLSearchParams(search);
  return params.get('mode') === 'consumer' ? 'consumer' : 'reviewer';
}

export function isConsumerMode(search = '') {
  return getPreviewMode(search) === 'consumer';
}

export function withPreviewMode(path, search = '') {
  const mode = getPreviewMode(search);
  if (mode !== 'consumer') return path;

  const separator = path.includes('?') ? '&' : '?';
  return `${path}${separator}mode=consumer`;
}

export function getDisplayTourTitle(tour, previewMode = 'reviewer') {
  const title = tour?.title || '';
  if (previewMode !== 'consumer') return title;
  return title.replace(/\s+Field Test$/i, '').trim() || title;
}

export function getDisplayTourDescription(tour, previewMode = 'reviewer') {
  const description = tour?.description || '';
  if (previewMode !== 'consumer') return description;
  return description
    .replace(' for testing Tour Engine as high-intent retail discovery', '')
    .replace(/ Store hours, stock, tax-free rules, and coordinates require field verification before publishing\.?/i, '')
    .trim() || description;
}

export function getDisplayTourBadge(tour, previewMode = 'reviewer') {
  const badge = tour?.access || tour?.price || '';
  if (previewMode !== 'consumer') return badge;
  return badge.replace(/field test/i, 'Preview').replace(/private preview/i, 'Preview').trim() || badge;
}
